const distance=(a,b)=>a&&b?Math.hypot(...a.map((v,i)=>v-b[i]))*100:null;
const mean=a=>a.length?a.reduce((s,v)=>s+v,0)/a.length:null;
export function deriveSignals(run){if(run.signals)return run.signals;const n=run.times.length,s={leftDistance:[],rightDistance:[],vlDistance:[],vrDistance:[],separation:[],leftSpeed:[],rightSpeed:[],balance:[]};const rawL=[],rawR=[];for(let i=0;i<n;i++){for(const [key,out]of [['left','leftDistance'],['right','rightDistance'],['vl','vlDistance'],['vr','vrDistance']])s[out].push(distance(run.tracks[key][i],run.tracks.head[i]));s.separation.push(distance(run.tracks.left[i],run.tracks.right[i]));const dt=i?run.times[i]-run.times[i-1]:0;rawL.push(i&&dt>0&&dt<=.25?distance(run.tracks.left[i],run.tracks.left[i-1])/dt:null);rawR.push(i&&dt>0&&dt<=.25?distance(run.tracks.right[i],run.tracks.right[i-1])/dt:null);if(i&&(!run.tracks.left[i]||!run.tracks.left[i-1]))rawL[i]=null;if(i&&(!run.tracks.right[i]||!run.tracks.right[i-1]))rawR[i]=null;const l=rawL.slice(Math.max(0,i-2),i+1),r=rawR.slice(Math.max(0,i-2),i+1);const ls=l.every(Number.isFinite)?mean(l):null,rs=r.every(Number.isFinite)?mean(r):null;s.leftSpeed.push(ls);s.rightSpeed.push(rs);s.balance.push(ls!==null&&rs!==null&&ls+rs>=1?(rs-ls)/(rs+ls):null);}run.signals=s;return s;}
export function sharedScales(runs,range,normalise){let d=0,v=0,f=normalise?100:0;for(const r of runs){const s=deriveSignals(r);f=Math.max(f,normalise?100:r.limit);for(let i=0;i<r.times.length;i++)if(r.times[i]>=range[0]&&r.times[i]<=range[1]){for(const k of ['leftDistance','rightDistance','vlDistance','vrDistance','separation'])d=Math.max(d,s[k][i]||0);v=Math.max(v,s.leftSpeed[i]||0,s.rightSpeed[i]||0);}}return {distance:Math.max(50,Math.ceil(d/50)*50),speed:Math.max(10,Math.ceil(v/25)*25),factor:Math.max(.15,f),normalise};}
export function summariseRun(run,[start,end]){const s=deriveSignals(run);let left=0,right=0;const factors=[];const balances=[];for(let i=0;i<run.times.length;i++){if(run.times[i]<start||run.times[i]>end)continue;if(Number.isFinite(run.factor[i])&&run.tracks.head[i])factors.push(run.factor[i]);if(Number.isFinite(s.balance[i]))balances.push(s.balance[i]);if(i&&run.times[i-1]>=start){left+=distance(run.tracks.left[i],run.tracks.left[i-1])||0;right+=distance(run.tracks.right[i],run.tracks.right[i-1])||0;}}const total=left+right;const cap=factors.length?100*factors.filter(v=>v>=run.limit*.99).length/factors.length:0;return {leftPath:left,rightPath:right,leftShare:total?left/total:null,meanFactor:mean(factors),nearCap:cap,leftFaster:balances.length?100*balances.filter(v=>v<-.2).length/balances.length:null,rightFaster:balances.length?100*balances.filter(v=>v>.2).length/balances.length:null,text:`Physical path: L ${(left/100).toFixed(1)} m, R ${(right/100).toFixed(1)} m${total?`; left accounts for ${(left/total*100).toFixed(0)}% of path length`:''}. Mean factor ${(mean(factors)||0).toFixed(3)}; ${cap.toFixed(0)}% of valid samples near the ${run.limit} ceiling. ${cap>50?'A flat factor near the ceiling can conceal continued hand adjustment.':'These are movement descriptions, not inferred effort or strategy.'}`};}
export function drawTimeSeries(canvas,run,range,time,scales){const rect=canvas.getBoundingClientRect(),w=Math.max(200,rect.width),h=230,ratio=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(w*ratio)||canvas.height!==h*ratio){canvas.width=Math.round(w*ratio);canvas.height=h*ratio;}const c=canvas.getContext('2d'),paper=!!scales.paper;c.setTransform(ratio,0,0,ratio,0,0);c.fillStyle=paper?'#ffffff':'#132237';c.fillRect(0,0,w,h);const s=deriveSignals(run),left=43,right=w-10,pw=right-left,span=Math.max(.1,range[1]-range[0]);const xpos=t=>left+(t-range[0])/span*pw;const specs=[{top:22,height:47,max:scales.distance,label:'Head distances + interhand (grey) · cm',lines:[['leftDistance','#4f9aff',false],['rightDistance','#eea04c',false],['vlDistance','#4f9aff',true],['vrDistance','#eea04c',true],['separation','#aebcca',true]]},{top:91,height:47,max:scales.speed,label:'Physical speed · cm/s',lines:[['leftSpeed','#4f9aff',false],['rightSpeed','#eea04c',false]]},{top:160,height:43,max:scales.factor,label:scales.normalise?'Factor · % of ceiling':'Amplification factor',lines:[['factor','#63cfad',false]]}];
for(const spec of specs){const bottom=spec.top+spec.height;c.fillStyle=paper?'#4b6377':'#9ab2c8';c.font='10px system-ui';c.fillText(spec.label,8,spec.top-7);c.font='9px system-ui';c.fillText(String(spec.max),3,spec.top+3);c.fillText('0',29,bottom+3);c.strokeStyle=paper?'#dfe6ed':'#2c4058';c.lineWidth=.6;for(let k=0;k<=2;k++){const yy=spec.top+k*spec.height/2;c.beginPath();c.moveTo(left,yy);c.lineTo(right,yy);c.stroke();}for(const [key,color,dashed]of spec.lines){const vals=key==='factor'?run.factor:s[key];c.beginPath();c.strokeStyle=paper?({'#4f9aff':'#2a65aa','#eea04c':'#b56a1c','#63cfad':'#247f61','#aebcca':'#6b7784'}[color]||color):color;c.lineWidth=1.2;c.setLineDash(dashed?[3,2]:[]);let pen=false;for(let i=0;i<run.times.length;i++){let value=vals[i];if(key==='factor'&&scales.normalise)value=value/run.limit*100;if(run.times[i]<range[0]||run.times[i]>range[1]||!Number.isFinite(value)){pen=false;continue;}const x=xpos(run.times[i]),y=bottom-value/spec.max*spec.height;if(!pen)c.moveTo(x,y);else c.lineTo(x,y);pen=true;}c.stroke();c.setLineDash([]);}if(spec.lines[0][0]==='factor'){const value=scales.normalise?100:run.limit;c.setLineDash([4,3]);c.strokeStyle='#8b9db0';c.beginPath();c.moveTo(left,bottom-value/spec.max*spec.height);c.lineTo(right,bottom-value/spec.max*spec.height);c.stroke();c.setLineDash([]);}if(time>=range[0]&&time<=range[1]){c.strokeStyle=paper?'#243d51':'#edf7ff';c.lineWidth=1;c.beginPath();c.moveTo(xpos(time),spec.top);c.lineTo(xpos(time),bottom);c.stroke();}}
for(const e of run.events){if(e.t<range[0]||e.t>range[1]||!['goal','early','audit'].includes(e.type))continue;c.strokeStyle={goal:'#63cfad',early:'#ed779c',audit:'#e8ce6c'}[e.type];c.beginPath();c.moveTo(xpos(e.t),204);c.lineTo(xpos(e.t),209);c.stroke();}c.fillStyle=paper?'#4b6377':'#91a9bf';c.font='9px system-ui';for(let k=0;k<=4;k++){const t=range[0]+span*k/4;c.fillText(t.toFixed(0)+'s',xpos(t)-7,219);}canvas.dataset.rangeStart=range[0];canvas.dataset.rangeEnd=range[1];canvas.dataset.plotLeft=left;canvas.dataset.plotRight=right;}
export function clickedTime(canvas,clientX){const rect=canvas.getBoundingClientRect(),x=clientX-rect.left,a=Number(canvas.dataset.rangeStart),b=Number(canvas.dataset.rangeEnd),l=Number(canvas.dataset.plotLeft),r=Number(canvas.dataset.plotRight);return a+Math.max(0,Math.min(1,(x-l)/(r-l)))*(b-a);}
